function showGameOver(){
  running=false;paused=false;
  document.getElementById('pause-overlay').style.display='none';
  document.getElementById('btn-pause').textContent='⏸';
  setTimeout(()=>bgmFadeIn(0.38),800);
  _pendingScore=score;_pendingLevel=level;_pendingWin=false;autoSaveScore(score,level,false);
  const s=document.getElementById('screen');
  s.className='gameover-screen';
  s.innerHTML=`<div id="screen-overlay"></div>
  <div class="tdeco">— ბრძოლა დასრულდა —</div>
  <h1 style="font-size:38px;color:#c83030;text-shadow:0 0 40px rgba(200,30,30,0.8),0 2px 0 #0a0200;">სიმონა დაეცა</h1>
  <div class="tsub">გამარჯვება ხვალ მოვა</div>
  <div class="sbox"><p>ქულა: <strong style="color:#d09820;font-size:22px;" class="score-reveal">${score.toLocaleString()}</strong><br><span style="color:#7a5820;font-size:10px;letter-spacing:2px;">დონე ${level} • ${level<=2?'ადვილი':level<=4?'საშუალო':'რთული'}</span></p></div>
  <button class="sbtn" onclick="document.getElementById('screen').style.display='none';lbShow()">🏆 რეკორდები</button>`;
  s.style.display='flex';
}
function showVictory(){
  running=false;paused=false;
  document.getElementById('pause-overlay').style.display='none';
  document.getElementById('btn-pause').textContent='⏸';
  setTimeout(()=>bgmFadeIn(0.42),800);
  _pendingScore=score;_pendingLevel=level;_pendingWin=true;autoSaveScore(score,level,true);
  const s=document.getElementById('screen');
  s.className='victory-screen';
  s.innerHTML=`<div id="screen-overlay"></div>
  <div class="tdeco" style="color:#c8a840;letter-spacing:8px;">— გამარჯვება! —</div>
  <h1 style="font-size:48px;">⛪</h1>
  <h1 style="font-size:28px;letter-spacing:6px;margin-top:-8px;">ეკლესია!</h1>
  <div class="tsub">სამშობლო გადარჩა</div>
  <div class="sbox"><p>ქულა: <strong style="color:#f0d020;font-size:24px;" class="score-reveal">${score.toLocaleString()}</strong><br><span style="font-size:11px;color:#907030;">სიმონა თამარის ეკლესიამდე მივიდა!</span></p></div>
  <button class="sbtn" style="background:linear-gradient(180deg,#5c380a,#2e1a04);border-color:#d8a820;" onclick="document.getElementById('screen').style.display='none';lbShow()">🏆 რეკორდები</button>`;
  s.style.display='flex';
}

function showIntro(onDone){
  // Build overlay
  let ov=document.getElementById('intro-overlay');
  if(!ov){
    ov=document.createElement('div');
    ov.id='intro-overlay';
    ov.style.cssText='position:fixed;inset:0;background:rgba(4,2,0,0.97);z-index:400;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:\'Noto Sans Georgian\',sans-serif;';
    const ic=document.createElement('canvas');
    ic.id='intro-canvas';ic.style.cssText='position:absolute;inset:0;width:100%;height:100%;';
    const dlg=document.createElement('div');
    dlg.id='intro-dialog';dlg.style.cssText='position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:14px;pointer-events:none;margin-top:60px;';
    ov.appendChild(ic);ov.appendChild(dlg);
    document.body.appendChild(ov);
  }
  ov.style.display='flex';
  const ic=document.getElementById('intro-canvas');
  ic.width=window.innerWidth;ic.height=window.innerHeight;
  const cx=ic.getContext('2d');
  const dlg=document.getElementById('intro-dialog');
  dlg.innerHTML='';

  if(!document.getElementById('introLineStyle')){
    const st=document.createElement('style');st.id='introLineStyle';
    st.textContent='@keyframes introLine{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}';
    document.head.appendChild(st);
  }

  const IW=ic.width,IH=ic.height;
  let lx=IW*1.1,ly=IH*0.52;
  let phase=0,lineIdx=0,t0=performance.now(),raf;

  const lines=[
    {speaker:'სიმონა',text:'მოდი აქ, შე აბდალა!'},
    {speaker:'ბატონი',text:'მიშველეთ! მიშველეთ!'},
  ];

  // Preload images
  const _sceneImg=new Image();
  _sceneImg.src='data:image/jpeg;base64,';
  const _simonaImg=new Image();
  _simonaImg.src='data:image/jpeg;base64,';

  function drawScene(ts){
    cx.clearRect(0,0,IW,IH);
    // === DRAW BACKGROUND IMAGE (full uploaded scene) ===
    if(_sceneImg.complete && _sceneImg.naturalWidth>0){
      // Draw full image stretched to canvas
      cx.drawImage(_sceneImg, 0, 0, IW, IH);
      // Patch over the Batoni area in the background using nearby forest region
      // Source image is 1536x1024; Batoni is at roughly x=870-1370, y=240-960
      // Patch with forest from x=350-580 region (clean area)
      const imgW=1536, imgH=1024;
      const patchSrcX=350, patchSrcY=240, patchSrcW=230, patchSrcH=720;
      const batBgX=870, batBgY=240, batBgW=510, batBgH=720;
      // Scale to canvas coords
      const scX=IW/imgW, scY=IH/imgH;
      // Draw two copies of the clean patch to cover Batoni area
      cx.drawImage(_sceneImg, patchSrcX, patchSrcY, patchSrcW, patchSrcH,
        batBgX*scX, batBgY*scY, patchSrcW*scX*1.1, patchSrcH*scY);
      cx.drawImage(_sceneImg, patchSrcX, patchSrcY, patchSrcW, patchSrcH,
        (batBgX+230)*scX, batBgY*scY, (patchSrcW+50)*scX*1.1, patchSrcH*scY);
    } else {
      // Fallback: dark background while loading
      cx.fillStyle='#1a2e10'; cx.fillRect(0,0,IW,IH);
    }

    // === სიმონა — from image, stays in background (static) ===
    // Simona is already in the background image at her natural position, no need to draw again

    // === ბატონი — drawn from source image at animated position ===
    if(_sceneImg.complete && _sceneImg.naturalWidth>0){
      const imgW=1536, imgH=1024;
      // Batoni source region in original image
      const bSrcX=870, bSrcY=200, bSrcW=520, bSrcH=780;
      // Target size on canvas (proportional)
      const bDrawW=IW*0.34, bDrawH=IH*0.76;
      // Animated position: lx is the center X, ly is center Y
      const bob=Math.sin(ts*0.008)*4;
      const bDrawX=lx - bDrawW*0.48;
      const bDrawY=ly - bDrawH*0.42 + bob;
      cx.drawImage(_sceneImg, bSrcX, bSrcY, bSrcW, bSrcH,
        bDrawX, bDrawY, bDrawW, bDrawH);
    }
  }
  function showLine(idx){
    dlg.innerHTML='';
    if(idx>=lines.length)return;
    const l=lines[idx];
    const isSimona=(idx===0);
    const avatarSrc=isSimona?'data:image/jpeg;base64,':'';
    const wrap=document.createElement('div');
    wrap.style.cssText='background:rgba(4,2,0,0.96);border:1px solid rgba(180,120,30,0.7);border-radius:13px;padding:16px 22px;max-width:380px;display:flex;align-items:center;gap:14px;animation:introLine 0.35s ease-out;box-shadow:0 6px 28px rgba(0,0,0,0.9);';
    const batoniAvatar='data:image/jpeg;base64,';
    const avatarHtml=isSimona
      ?`<img src="${avatarSrc}" style="width:80px;height:80px;border-radius:50%;border:2px solid #c89820;object-fit:cover;flex-shrink:0;box-shadow:0 0 12px rgba(200,150,30,0.5);">`
      :`<img src="${batoniAvatar}" style="width:80px;height:80px;border-radius:50%;border:2px solid #cc3030;object-fit:cover;object-position:center top;flex-shrink:0;box-shadow:0 0 12px rgba(200,30,30,0.5);">`;
    wrap.innerHTML=avatarHtml+`<div><div style="font-size:13px;letter-spacing:2px;color:#c89820;text-transform:uppercase;margin-bottom:8px;font-weight:700;">${l.speaker}</div><div style="font-size:22px;color:#fff8e0;font-weight:900;line-height:1.35;text-shadow:0 2px 8px rgba(0,0,0,0.8);">${l.text}</div></div>`;
    dlg.appendChild(wrap);
  }

  function tick(ts){
    const elapsed=ts-t0;
    if(phase===0){
      lx=Math.max(IW*0.60,lx-2.2);
      if(lx<=IW*0.60){phase=1;t0=ts;showLine(0);}
    }
    if(phase===1){
      if(elapsed>3000&&lineIdx===0){lineIdx=1;showLine(1);}
      if(elapsed>7200){phase=2;t0=ts;dlg.innerHTML='';}
    }
    if(phase===2){
      lx+=3.5;
      if(lx>IW*1.2){
        cancelAnimationFrame(raf);
        ov.style.display='none';
        onDone();return;
      }
    }
    drawScene(ts);
    raf=requestAnimationFrame(tick);
  }
  raf=requestAnimationFrame(tick);
}

function spawnLandlordNPC(){
  enemies.push({
    x:player?player.x+130:P.x+130,
    y:player?player.y:P.y,
    r:13,hp:1,maxHp:1,
    vx:0,vy:0,ang:Math.PI,
    patrol:{cx:P.x+130,cy:P.y,radius:40,t:0,spd:0.1},
    sT:9999,alive:true,hf:0,wf:0,
    etype:'landlord',
    isNPC:true,
    alertTimer:0,state:'patrol',flankTimer:0,groupId:0,
    retreating:false,retreatTimer:0
  });
  showBanner('მემამულე გამოჩნდა!\nმოკალი იგი!');
}

